# ── Levels ───────────────────────────────────────────────────────────────────
FOUND = -8.0
Y_PED, Y_CAP, Y_ENT, Y_COR = 2.0, 29.0, 32.6, 34.0       # pedestal, top of the order, frieze, cornice
Y_ATT, Y_ACOR, Y_TOP = 43.6, 44.4, 45.44                 # attic, its cornice, balustrade top
Y_ROOF = 45.0
Z_FRONT, Z_SIDE = 134.4, 133.0                           # wall of the central and side parts of the façade
G_KNOTS = ([120.0, 136.0, 225.0, 322.0, 440.0], [0.0, 0.0, -3.0, -6.0, -7.3])


def g(z):
    """Level of the paving of the square at z (y)."""
    return np.interp(z, *G_KNOTS)


def tint(c, k=0.012):
    return tuple(np.clip(np.array(c) * (1 + rng.normal(0, k)), 0, 1))


def B(x0, x1, y0, y1, z0, z1, c):
    return box(x1 - x0, y1 - y0, z1 - z0, c).T((x0 + x1) / 2, y0, (z0 + z1) / 2)


def sphere(r, c, seg=10, rings=6):
    prof = [(r * math.sin(t), -r * math.cos(t)) for t in np.linspace(0, math.pi, rings + 1)]
    return lathe(prof, c, seg).T(0, r, 0)


def flat(pts, w, c):
    """A flat convex polygon [(x, y)] in the plane z = w, facing +z."""
    n = len(pts)
    m = Mesh([(u, y, w) for u, y in pts], [(0, i, i + 1) for i in range(1, n - 1)], c)
    if sum(pts[i][0] * pts[(i + 1) % n][1] - pts[(i + 1) % n][0] * pts[i][1] for i in range(n)) < 0:
        m.f = m.f[:, ::-1]
    return m


def prism(pts, w0, w1, c):
    """A convex profile [(x, y)] extruded along z from w0 to w1."""
    n = len(pts)
    if sum(pts[i][0] * pts[(i + 1) % n][1] - pts[(i + 1) % n][0] * pts[i][1] for i in range(n)) < 0:
        pts = pts[::-1]
    V = [(u, y, w) for w in (w0, w1) for u, y in pts]
    F = [(n, n + i, n + i + 1) for i in range(1, n - 1)] + [(0, i + 1, i) for i in range(1, n - 1)]
    for i in range(n):
        j = (i + 1) % n
        F += [(i, j, n + j), (i, n + j, n + i)]
    return Mesh(V, F, c)


def arch_pts(u, y0, ys, half, seg=8):
    return [(u - half, y0), (u + half, y0)] + [(u + half * math.cos(a), ys + half * math.sin(a))
                                                for a in np.linspace(0, math.pi, seg + 1)]


def to_frame(m, origin, t):
    """Local (u along t, y, w outwards = (t_z, -t_x)) -> model, keeping the winding (frame (-t, y, n) is right-handed:
    so u runs along -t and t is the direction of the ring)."""
    t = np.asarray(t, float); n = np.array([t[1], -t[0]])
    u, y, w = m.v[:, 0], m.v[:, 1], m.v[:, 2]
    x = origin[0] - u * t[0] + w * n[0]
    z = origin[1] - u * t[1] + w * n[1]
    m.v = np.stack([x, y, z], 1)
    return m


def rot_y(m, a, x=0.0, z=0.0):
    """Rotate about +y so that local +z points to the direction angle a (radians, in the x/z plane, from +x)."""
    # local +z -> (cos a, sin a) in (x, z)
    c, s = math.cos(a), math.sin(a)
    X, Z = m.v[:, 0].copy(), m.v[:, 2].copy()
    m.v[:, 0] = X * s + Z * c + x
    m.v[:, 2] = -X * c + Z * s + z
    return m


def figure(h, c=TRAV_L, arm=1):
    """A stylised standing statue (robe, head, an arm), standing on y = 0 at x = z = 0, facing +z."""
    prof = [(0.19 * h, 0), (0.17 * h, 0.35 * h), (0.14 * h, 0.6 * h), (0.15 * h, 0.74 * h), (0.06 * h, 0.8 * h), (0, 0.81 * h)]
    out = [lathe(prof, c, 7), sphere(0.075 * h, c, 6, 3).T(0, 0.81 * h, 0)]
    out.append(tube([(arm * 0.09 * h, 0.7 * h, 0), (arm * 0.2 * h, 0.58 * h + 0.12 * h, 0.06 * h)], 0.035 * h, c, 5))
    return merge(out)


def ring_band(P, d_out, d_in, y0, y1, c, top=True):
    return extrude(offset(P, d_out), y0, y1, c, holes=[offset(P, d_in)], top=top)


def arc(cx, cz, r, a0, a1, n):
    return [(cx + r * math.cos(a), cz + r * math.sin(a)) for a in np.linspace(math.radians(a0), math.radians(a1), n)]


# ── Plan of the basilica ─────────────────────────────────────────────────────
def basilica_ring():
    """Symmetric outline: the north half of OSM way 244159210 (cleaned), apses as fitted arcs, mirrored."""
    half = [(0.0, Z_FRONT), (27.9, Z_FRONT), (27.9, Z_SIDE), (57.35, Z_SIDE), (57.35, 120.1), (41.4, 120.1),
            (41.4, 118.4), (36.3, 118.4), (36.3, 75.4), (47.6, 75.4), (47.6, 52.4), (52.4, 52.4), (52.4, 43.2),
            (49.6, 41.4), (49.7, 32.8), (53.7, 31.2), (58.6, 23.9)]
    half += arc(59.7, 0.0, 18.6, 80, -82, 15)                                 # north transept apse
    half += [(62.8, -22.3), (57.4, -30.1), (52.8, -34.1), (52.8, -41.6), (54.6, -41.6), (54.6, -57.9),
             (41.4, -58.2), (41.5, -55.2), (34.0, -55.3), (31.6, -58.5), (22.3, -66.9), (19.1, -66.2)]
    half += arc(0.0, -62.8, 18.4, -12, -90, 11)[1:]                           # west apse (half)
    full = half + [(-x, z) for x, z in reversed(half[1:-1])]
    return full


RING = basilica_ring()


# ── Michelangelo's elevations: giant pilasters, windows, attic ──────────────
def pilaster(u, w=2.6, d=0.9):
    return [B(u - w / 2, u + w / 2, Y_PED, Y_CAP - 1.6, -0.1, d, TRAV_L),
            B(u - w / 2 - 0.25, u + w / 2 + 0.25, Y_CAP - 1.6, Y_CAP, -0.1, d + 0.25, TRAV_L),      # capital
            B(u - w / 2 - 0.3, u + w / 2 + 0.3, 0.0, Y_PED, -0.1, d + 0.3, TRAV_D),                # pedestal
            B(u - w / 2 + 0.1, u + w / 2 - 0.1, Y_COR, Y_ATT, -0.1, d * 0.55, TRAV_L)]             # attic strip


def window(u, y0, y1, w, ped=None, frame=TRAV_L):
    out = [flat([(u - w / 2, y0), (u + w / 2, y0), (u + w / 2, y1), (u - w / 2, y1)], 0.08, GLASS),
           B(u - w / 2 - 0.45, u - w / 2, y0, y1, -0.1, 0.3, frame), B(u + w / 2, u + w / 2 + 0.45, y0, y1, -0.1, 0.3, frame),
           B(u - w / 2 - 0.55, u + w / 2 + 0.55, y0 - 0.45, y0, -0.1, 0.4, frame),
           B(u - w / 2 - 0.45, u + w / 2 + 0.45, y1, y1 + 0.4, -0.1, 0.35, frame)]
    if ped == "tri":
        out.append(prism([(u - w / 2 - 0.8, y1 + 0.4), (u + w / 2 + 0.8, y1 + 0.4), (u, y1 + 0.4 + w * 0.32)], -0.1, 0.5, frame))
    elif ped == "seg":
        pts = [(u - w / 2 - 0.8, y1 + 0.4), (u + w / 2 + 0.8, y1 + 0.4)] + \
              [(u + (w / 2 + 0.8) * math.cos(a), y1 + 0.4 + w * 0.28 * math.sin(a)) for a in np.linspace(0.3, math.pi - 0.3, 6)]
        out.append(prism(pts, -0.1, 0.5, frame))
    return out


def body_elevations():
    """Pilasters at the corners and every ~7.5 m along the outline (the apses included), windows in the bays
    between them (not on the façade, which has its own)."""
    P = RING if ring_area(RING) > 0 else RING[::-1]
    n = len(P)
    # start the walk at a corner of the façade so that no run is cut in two
    k0 = next(i for i in range(n) if P[i][1] > Z_SIDE - 0.2 and P[(i + 1) % n][1] < Z_SIDE - 0.2)
    E = []
    for j in range(n):
        a, b = np.array(P[(k0 + j) % n]), np.array(P[(k0 + j + 1) % n])
        if a[1] > Z_SIDE - 0.2 and b[1] > Z_SIDE - 0.2:
            break
        E.append((a, b, float(np.linalg.norm(b - a))))
    S0 = np.concatenate([[0.0], np.cumsum([e[2] for e in E])])          # arc length at the start of each edge
    marks = [0.6]
    for i in range(1, len(E)):
        d0 = (E[i - 1][1] - E[i - 1][0]) / E[i - 1][2]; d1 = (E[i][1] - E[i][0]) / E[i][2]
        turn = abs(math.degrees(math.atan2(d0[0] * d1[1] - d0[1] * d1[0], float(np.dot(d0, d1)))))
        if turn > 25:
            for sm in (S0[i] - 1.4, S0[i] + 1.4):
                if sm - marks[-1] > 2.5:
                    marks.append(sm)
    marks.append(S0[-1] - 0.6)
    full = [marks[0]]
    for a_, b_ in zip(marks[:-1], marks[1:]):                           # fill the long runs
        k = max(0, round((b_ - a_) / 7.5) - 1)
        full += [a_ + (b_ - a_) * j / (k + 1) for j in range(1, k + 1)] + [b_]

    def where(sv):
        i = int(np.clip(np.searchsorted(S0, sv, side="right") - 1, 0, len(E) - 1))
        return i, sv - S0[i]
    per_edge = {}
    for sv in full:
        i, d = where(sv)
        per_edge.setdefault(i, []).extend(pilaster(E[i][2] - d))
    for q, (a_, b_) in enumerate(zip(full[:-1], full[1:])):
        gap = b_ - a_
        if gap < 4.6:
            continue
        i, d = where((a_ + b_) / 2)
        L = E[i][2]
        ww = min(2.8, gap - 2.9)
        u = L - d
        loc = window(u, 9.5, 17.0, ww, ped="tri" if q % 2 else "seg")
        loc += window(u, 21.0, 25.5, ww * 0.8) + window(u, 37.0, 41.0, ww * 0.7, frame=TRAV)
        per_edge.setdefault(i, []).extend(loc)
    out = []
    for i, loc in per_edge.items():
        a, b, L = E[i]
        out.append(to_frame(merge(loc), b, (b - a) / L))
    return out


def body():
    parts = [extrude(RING, FOUND, Y_ROOF, TRAV, top_c=ROOF)]
    parts.append(ring_band(RING, 0.35, -0.4, FOUND, Y_PED, TRAV_D, top=True))                # plinth
    parts.append(ring_band(RING, 0.55, -0.4, Y_CAP, Y_ENT, tint(TRAV_L, 0.004)))             # architrave and frieze
    parts.append(ring_band(RING, 1.5, -0.4, Y_ENT, Y_COR, TRAV_L))                           # cornice
    parts.append(ring_band(RING, 0.8, -0.4, Y_ATT, Y_ACOR, TRAV_L))                          # attic cornice
    parts.append(ring_band(RING, 0.35, -0.55, Y_ACOR, Y_TOP, TRAV_L))                        # parapet
    parts += body_elevations()
    return merge(parts)


# ── Roofs over the arms, small domes ─────────────────────────────────────────
def gable_x(x0, x1, zc, half, y0, y1, c=LEAD):
    """Gabled roof running along x (ridge at z = zc)."""
    m = prism([(zc - half, y0), (zc + half, y0), (zc, y1)], x0, x1, c)
    m.v = m.v[:, [2, 1, 0]]; m.f = m.f[:, ::-1]
    return m


def gable_z(z0, z1, xc, half, y0, y1, c=LEAD):
    return prism([(xc - half, y0), (xc + half, y0), (xc, y1)], z0, z1, c)


def half_cone(cx, cz, r, y0, y1, a0, a1, c=LEAD, n=10):
    """Half (or part) of a cone: the roof of an apse, from angle a0 to a1 (degrees in x/z)."""
    a = np.radians(np.linspace(a0, a1, n + 1))
    V = [(cx + r * math.cos(t), y0, cz + r * math.sin(t)) for t in a] + [(cx, y1, cz)]
    F = [(i, n + 1, i + 1) for i in range(n)]
    return orient_up(Mesh(V, F, c))


def orient_up(m):
    f = m.f[0]
    if np.cross(m.v[f[1]] - m.v[f[0]], m.v[f[2]] - m.v[f[0]])[1] < 0:
        m.f = m.f[:, ::-1]
    return m


def orient_out(m):
    """Flip every face whose normal points towards the centre of the (convex) mesh."""
    ctr = m.v.mean(0)
    a, b, c = m.v[m.f[:, 0]], m.v[m.f[:, 1]], m.v[m.f[:, 2]]
    bad = np.einsum("ij,ij->i", np.cross(b - a, c - a), (a + b + c) / 3 - ctr) < 0
    m.f[bad] = m.f[bad][:, ::-1]
    return m


def roofs():
    out = []
    H0, H1, W = Y_ROOF + 0.02, 50.2, 12.5
    out.append(gable_z(30.0, 116.0, 0.0, W, H0, H1))                                 # nave
    out.append(gable_z(-62.8, -30.0, 0.0, W, H0, H1))                                # west arm
    out.append(half_cone(0.0, -62.8, W, H0, H1, 180, 360))
    for s in (-1, 1):                                                                 # transepts
        out.append(gable_x(s * 30.0, s * 59.7, 0.0, W, H0, H1))
        out.append(half_cone(s * 59.7, 0.0, W, H0, H1, -90 if s > 0 else 90, 90 if s > 0 else 270))
        # small oval domes over the aisles of Maderno's nave (estimated)
        for zc in (84.0, 97.0, 110.0):
            prof = [(4.6 * math.cos(t), Y_ROOF + 3.4 * math.sin(t)) for t in np.linspace(0, math.pi / 2, 6)]
            out.append(lathe(prof, LEAD, 16).S(1.0, 1.0, 0.8).T(s * 24.5, 0, zc))
            out.append(cyl(0.9, 0.9, 1.6, TRAV_L, 8).T(s * 24.5, Y_ROOF + 3.3, zc))
            out.append(cyl(1.0, 0.1, 1.0, LEAD, 8).T(s * 24.5, Y_ROOF + 4.9, zc))
        # little domed turrets of the stairs (OSM ways 1420231564, 1580924584–86)
        for zc in (-17.0, 14.5):
            x = s * 53.6
            out.append(cyl(4.3, 4.3, 2.6, TRAV, 16).T(x, Y_ROOF, zc))
            out.append(lathe([(4.5, 0), (4.0, 1.3), (2.6, 2.4), (0.8, 2.9), (0.0, 3.0)], LEAD, 16).T(x, Y_ROOF + 2.6, zc))
            out.append(cyl(0.6, 0.5, 1.4, TRAV_L, 8).T(x, Y_ROOF + 5.5, zc))
    return merge(out)


def minor_dome(cx, cz):
    """The four corner domes (Vignola, della Porta): drum with paired columns, ribbed lead dome, lantern."""
    out = []
    y0 = Y_ROOF
    out.append(cyl(9.6, 9.6, 2.2, TRAV, 8).R(0, math.pi / 8, 0).T(cx, y0, cz))                     # octagonal base
    out.append(cyl(8.0, 8.0, 9.4, TRAV, 24).T(cx, y0 + 2.2, cz))
    for k in range(8):
        a = 2 * math.pi * k / 8 + math.pi / 8
        n = np.array([math.cos(a), math.sin(a)])
        for s in (-1, 1):
            t = np.array([-n[1], n[0]]) * 0.75 * s
            p = np.array([cx, cz]) + n * 8.7 + t
            out.append(cyl(0.38, 0.33, 7.6, TRAV_L, 8).T(p[0], y0 + 2.4, p[1]))
        win = merge([B(-0.8, 0.8, y0 + 4.6, y0 + 8.4, -0.1, 0.25, GLASS), B(-1.1, 1.1, y0 + 8.4, y0 + 8.9, -0.1, 0.35, TRAV_L)])
        b = a + math.pi / 8
        out.append(rot_y(win, b, cx + 8.0 * math.cos(b), cz + 8.0 * math.sin(b)))
    out.append(cyl(9.3, 9.3, 1.0, TRAV_L, 24).T(cx, y0 + 10.0, cz))
    out.append(cyl(8.2, 8.2, 1.6, TRAV, 24).T(cx, y0 + 11.0, cz))
    ys = y0 + 12.6
    prof = [(8.4 * math.cos(t), ys + 9.6 * math.sin(t)) for t in np.linspace(0, 1.36, 9)]
    out.append(lathe(prof + [(0.0, prof[-1][1] + 0.05)], LEAD, 24).T(cx, 0, cz))
    for k in range(8):
        a = 2 * math.pi * k / 8 + math.pi / 8
        out.append(tube([(cx + (r + 0.15) * math.cos(a), y + 0.1, cz + (r + 0.15) * math.sin(a)) for r, y in prof[:-1]], 0.3, TRAV_L, 4))
    yt = prof[-1][1]
    out += [cyl(1.9, 1.9, 4.2, TRAV_L, 12).T(cx, yt - 0.2, cz),
            cyl(2.2, 2.2, 0.5, TRAV_L, 12).T(cx, yt + 4.0, cz),
            lathe([(2.0, 0), (1.3, 0.8), (0.4, 1.8), (0.0, 2.0)], LEAD, 12).T(cx, yt + 4.5, cz),
            sphere(0.4, GOLD, 8, 5).T(cx, yt + 6.4, cz),
            B(cx - 0.08, cx + 0.08, yt + 7.1, yt + 8.6, cz - 0.08, cz + 0.08, GOLD),
            B(cx - 0.45, cx + 0.45, yt + 8.0, yt + 8.15, cz - 0.08, cz + 0.08, GOLD)]
    return out


# ── Michelangelo's dome ──────────────────────────────────────────────────────
def dome():
    out = []
    # the platform above the roofs (OSM way 149240100: an octagon ~64 m across)
    oc = [(30.9, 15.9), (15.5, 31.7), (-15.5, 31.7), (-30.9, 15.9), (-30.9, -15.9), (-15.5, -31.7), (15.5, -31.7), (30.9, -15.9)]
    out.append(extrude(oc, Y_ROOF - 0.5, 50.6, TRAV, top_c=ROOF))
    out.append(extrude(offset(oc, 0.5), 50.6, 51.4, TRAV_L, top_c=ROOF))
    out.append(cyl(27.0, 27.0, 0.8, TRAV_D, 48).T(0, 51.3, 0))
    # drum: wall, 16 buttresses with paired columns, windows, entablature, attic
    R = 24.5
    out.append(cyl(R, R, 70.6 - 52.0, TRAV, 64, caps=False).T(0, 52.0, 0))
    for k in range(16):
        a = 2 * math.pi * k / 16 + math.pi / 16
        n = np.array([math.cos(a), math.sin(a)])
        but = merge([B(-2.3, 2.3, 52.0, 68.4, -4.5, 0.4, TRAV),                       # buttress
                     B(-2.9, 2.9, 52.0, 53.2, -4.5, 1.3, TRAV_D),                     # its pedestal
                     B(-2.9, 2.9, 68.4, 70.6, -4.5, 1.6, TRAV_L),                     # entablature breaking forward
                     B(-3.1, 3.1, 70.0, 70.7, -4.5, 2.0, TRAV_L)])
        for s in (-1, 1):                                                              # paired columns
            but = merge([but, cyl(0.62, 0.54, 13.6, TRAV_L, 10).T(s * 1.55, 53.6, 0.9),
                         cyl(0.75, 0.75, 0.45, TRAV_L, 10).T(s * 1.55, 53.2, 0.9),
                         B(s * 1.55 - 0.85, s * 1.55 + 0.85, 67.2, 68.4, 0.05, 1.75, TRAV_L)])
        out.append(rot_y(but, a, n[0] * (R + 4.1), n[1] * (R + 4.1)))
        b = a + math.pi / 16                                                          # window between
        nb = np.array([math.cos(b), math.sin(b)])
        win = window(0.0, 56.5, 63.5, 2.6, ped="tri" if k % 2 else "seg")
        out.append(rot_y(merge(win), b, nb[0] * R, nb[1] * R))
    out.append(cyl(R + 0.7, R + 0.7, 0.8, TRAV_L, 64).T(0, 70.0, 0))
    out.append(cyl(R + 0.2, R + 0.2, 6.2, TRAV, 64).T(0, 70.8, 0))                       # attic
    for k in range(16):                                                               # attic panels over the buttresses
        a = 2 * math.pi * k / 16 + math.pi / 16
        p = merge([B(-2.4, 2.4, 70.8, 77.0, -0.6, 0.5, TRAV_L), B(-1.6, 1.6, 72.2, 75.6, 0.4, 0.7, TRAV)])
        out.append(rot_y(p, a, math.cos(a) * (R + 0.2), math.sin(a) * (R + 0.2)))
    out.append(cyl(R + 0.9, R + 0.9, 0.6, TRAV_L, 64).T(0, 77.0, 0))
    # the shell: raised profile, lead, 16 travertine ribs, three rows of lucarnes
    ys, Rs, Hs = 77.6, 24.6, 33.4
    ts = np.linspace(0, math.acos(6.6 / Rs), 16)
    prof = [(Rs * math.cos(t), ys + Hs * math.sin(t)) for t in ts]
    out.append(lathe(prof + [(0.0, prof[-1][1] + 0.05)], LEAD, 64))
    for k in range(16):
        a = 2 * math.pi * k / 16 + math.pi / 16
        out.append(tube([((r + 0.35) * math.cos(a), y + 0.25, (r + 0.35) * math.sin(a)) for r, y in prof], 0.75, TRAV_L, 5))
        b = a + math.pi / 16
        for tt, sc in ((0.33, 1.0), (0.72, 0.85), (1.03, 0.7)):                      # lucarnes
            r, y = Rs * math.cos(tt), ys + Hs * math.sin(tt)
            luc = merge([B(-0.9 * sc, 0.9 * sc, -0.2, 2.2 * sc, -0.6, 0.6, TRAV_L),
                         flat([(-0.6 * sc, 0.1), (0.6 * sc, 0.1), (0.6 * sc, 1.7 * sc), (-0.6 * sc, 1.7 * sc)], 0.62, GLASS),
                         prism([(-1.1 * sc, 2.2 * sc), (1.1 * sc, 2.2 * sc), (0, 2.9 * sc)], -0.6, 0.7, LEAD_D)])
            out.append(rot_y(luc, b, math.cos(b) * (r + 0.2), math.sin(b) * (r + 0.2)).T(0, y, 0))
    yt = prof[-1][1]
    # lantern
    out += [cyl(7.8, 7.8, 0.8, TRAV_L, 32).T(0, yt - 0.3, 0),
            cyl(5.0, 5.0, 9.0, TRAV, 24).T(0, yt + 0.5, 0)]
    for k in range(8):
        a = 2 * math.pi * k / 8 + math.pi / 8
        n = np.array([math.cos(a), math.sin(a)])
        for s in (-1, 1):
            p = n * 6.0 + np.array([-n[1], n[0]]) * 0.55 * s
            out.append(cyl(0.3, 0.26, 7.6, TRAV_L, 8).T(p[0], yt + 0.9, p[1]))
        out.append(rot_y(B(-0.9, 0.9, yt + 0.5, yt + 9.5, -0.6, 0.6, TRAV), a, n[0] * 5.7, n[1] * 5.7))
        b = a + math.pi / 8
        out.append(rot_y(flat(arch_pts(0.0, yt + 2.0, yt + 6.2, 0.9, 6), 0.05, DARK), b, math.cos(b) * 5.0, math.sin(b) * 5.0))
    y2 = yt + 9.5
    out += [cyl(6.6, 6.6, 1.4, TRAV_L, 24).T(0, y2, 0),
            cyl(5.3, 5.3, 1.6, TRAV, 24).T(0, y2 + 1.4, 0)]
    for k in range(8):                                                                # candelabra round the cone
        a = 2 * math.pi * k / 8 + math.pi / 8
        out.append(lathe([(0.35, 0), (0.25, 0.8), (0.12, 1.6), (0.0, 1.7)], TRAV_L, 6).T(math.cos(a) * 5.8, y2 + 1.4, math.sin(a) * 5.8))
    y3 = y2 + 3.0
    cone = [(5.2, 0.0), (4.4, 1.2), (3.0, 2.6), (1.8, 3.9), (1.1, 5.0), (0.8, 6.0)]
    out.append(lathe(cone, LEAD, 24).T(0, y3, 0))
    for k in range(8):
        a = 2 * math.pi * k / 8
        out.append(tube([((r + 0.1) * math.cos(a), y3 + y, (r + 0.1) * math.sin(a)) for r, y in cone], 0.16, TRAV_L, 4))
    y4 = y3 + 6.0
    out += [cyl(0.8, 0.6, 1.7, TRAV_L, 10).T(0, y4, 0),
            sphere(1.2, GOLD, 14, 8).T(0, y4 + 1.7, 0),
            B(-0.16, 0.16, y4 + 4.0, 136.6, -0.16, 0.16, GOLD),
            B(-1.2, 1.2, 134.6, 134.95, -0.16, 0.16, GOLD)]
    return merge(out)


# ── Maderno's façade ─────────────────────────────────────────────────────────
COLS = [5.4, 12.4, 16.85, 27.08]
SIDE_PIL = [31.6, 40.6, 49.2, 56.25]


def corinthian(x, z, r, y0, y1, c=TRAV_L):
    h = y1 - y0
    return [B(x - r - 0.35, x + r + 0.35, y0 - Y_PED, y0, z - r - 0.35, z + r + 0.35, TRAV_D),          # pedestal
            cyl(r * 1.22, r * 1.18, 0.7, c, 14).T(x, y0, z),
            cyl(r, r * 0.86, h - 3.6, tint(c, 0.01), 16, caps=False).T(x, y0 + 0.7, z),
            lathe([(r * 0.88, 0), (r * 1.05, 1.0), (r * 1.25, 2.2), (r * 1.3, 2.6), (0, 2.6)], c, 14).T(x, y1 - 2.9, z),
            B(x - r * 1.35, x + r * 1.35, y1 - 0.4, y1, z - r * 1.35, z + r * 1.35, c)]


def facade():
    out = []
    zc, zs = Z_FRONT, Z_SIDE
    zcol = 135.6
    for s in (-1, 1):
        for x in COLS:                                           # eight giant columns (OSM positions, symmetrised)
            out += corinthian(s * x, zcol, 1.32, Y_PED, Y_CAP)
            out.append(B(s * x - 1.4, s * x + 1.4, Y_PED, Y_CAP, zc - 0.1, zc + 0.4, TRAV_L))   # responds
        for x in SIDE_PIL:                                       # pilasters on the side walls
            w = 2.4 if x < 56 else 2.2
            out += [B(s * x - w / 2, s * x + w / 2, Y_PED, Y_CAP - 1.6, zs - 0.1, zs + 0.9, TRAV_L),
                    B(s * x - w / 2 - 0.3, s * x + w / 2 + 0.3, Y_CAP - 1.6, Y_CAP, zs - 0.1, zs + 1.2, TRAV_L),
                    B(s * x - w / 2 - 0.35, s * x + w / 2 + 0.35, 0.0, Y_PED, zs - 0.1, zs + 1.25, TRAV_D)]
        # entablature, cornice of the side parts
        x0, x1 = sorted((s * 27.9, s * 57.35))
        out += [B(x0, x1, Y_CAP, Y_ENT, zs - 0.1, zs + 1.2, tint(TRAV_L, 0.004)), B(x0 - 0.6, x1 + 0.6, Y_ENT, Y_COR, zs - 0.1, zs + 2.3, TRAV_L),
                B(x0, x1, Y_ATT, Y_ACOR, zs - 0.1, zs + 1.0, TRAV_L), B(x0, x1, 0.0, Y_PED, zs - 0.1, zs + 0.5, TRAV_D)]
        for x in SIDE_PIL:
            out.append(B(s * x - 1.1, s * x + 1.1, Y_COR, Y_ATT, zs - 0.1, zs + 0.6, TRAV_L))
    # the central part: entablature over the columns, inscription, pediment
    out += [B(-28.8, 28.8, Y_CAP, Y_ENT, zc - 0.1, 137.0, tint(TRAV_L, 0.004)),
            B(-29.5, 29.5, Y_ENT, Y_COR, zc - 0.1, 137.9, TRAV_L),
            B(-27.9, 27.9, 0.0, Y_PED, zc - 0.1, zc + 0.5, TRAV_D),
            B(-28.4, 28.4, Y_ATT, Y_ACOR, zc - 0.1, zc + 1.0, TRAV_L)]
    for i, x in enumerate(np.arange(-25.0, 25.01, 1.25)):                           # the letters of the inscription
        if i % 7 != 3:
            out.append(B(x - 0.38, x + 0.38, 30.9, 31.9, 137.0, 137.08, (0.35, 0.33, 0.3)))
    out.append(prism([(-15.2, Y_COR), (15.2, Y_COR), (0.0, 40.0)], zc - 0.1, 137.6, TRAV_L))          # pediment
    out.append(prism([(-12.6, Y_COR + 0.3), (12.6, Y_COR + 0.3), (0.0, 39.1)], 137.6, 137.75, TRAV))  # tympanum face
    for x in [0.0] + [s * c for s in (-1, 1) for c in COLS] + [s * c for s in (-1, 1) for c in SIDE_PIL]:
        if abs(x) > 8 or x == 0.0:
            zz = zc if abs(x) < 28 else zs
            out.append(B(x - 1.15, x + 1.15, Y_COR, Y_ATT, zz - 0.1, zz + 0.6, TRAV_L))         # attic strips
    # openings: portico entrances, loggia windows, attic windows
    out.append(flat(arch_pts(0.0, 0.0, 11.8, 3.2, 10), zc + 0.12, DARK))                          # central entrance
    out.append(B(-3.9, 3.9, 15.6, 16.3, zc - 0.1, zc + 1.6, TRAV_L))                                 # benediction balcony
    out += [B(-3.9, 3.9, 16.3, 17.3, zc + 1.2, zc + 1.6, TRAV_L)]
    out += [mm.T(0, 0, zc) for mm in window(0.0, 17.3, 25.8, 3.6, ped="tri")]
    for s in (-1, 1):
        for xb, kind in ((8.9, "seg"), (21.9, "tri")):
            x = s * xb
            if xb < 10:
                out.append(B(x - 1.6, x + 1.6, 0.0, 10.4, zc + 0.08, zc + 0.14, DARK))
                out.append(B(x - 2.1, x + 2.1, 10.4, 11.2, zc - 0.1, zc + 0.5, TRAV_L))
            else:
                out.append(flat(arch_pts(x, 0.0, 10.4, 2.4, 8), zc + 0.12, DARK))
            out.append(B(x - 2.0, x + 2.0, 15.9, 16.6, zc - 0.1, zc + 1.1, TRAV_L))
            out += [mm.T(0, 0, zc) for mm in window(x, 17.3, 24.0, 2.6, ped=kind)]
            out += [mm.T(0, 0, zc) for mm in window(x, 36.6, 40.8, 2.2, frame=TRAV)]
        for xb, kind in ((36.1, "seg"), (44.9, "tri")):
            x = s * xb
            out += [mm.T(0, 0, zs) for mm in window(x, 4.5, 11.5, 2.8, ped=kind)]
            out.append(B(x - 2.0, x + 2.0, 15.9, 16.6, zs - 0.1, zs + 1.0, TRAV_L))
            out += [mm.T(0, 0, zs) for mm in window(x, 17.3, 24.0, 2.6, ped="tri" if kind == "seg" else "seg")]
            out += [mm.T(0, 0, zs) for mm in window(x, 36.6, 40.8, 2.2, frame=TRAV)]
        x = s * 52.7                                                                 # the end arches
        out.append(flat(arch_pts(x, 0.0, 12.8, 2.6, 8), zs + 0.12, DARK))
        out += [mm.T(0, 0, zs) for mm in window(x, 20.0, 25.0, 2.2)]
        out += [mm.T(0, 0, zs) for mm in window(x, 36.6, 40.8, 2.0, frame=TRAV)]
    # balustrade with the 13 statues, the two clocks
    xs = [0.0] + [s * x for s in (-1, 1) for x in (5.4, 12.4, 16.85, 27.08, 33.5, 40.6)]
    for x in xs:
        zz = zc if abs(x) < 28 else zs
        out.append(B(x - 1.2, x + 1.2, Y_ACOR, Y_TOP + 0.5, zz - 0.4, zz + 1.4, TRAV_L))
        st = figure(5.7, WHITE, arm=1 if x <= 0 else -1).T(x, Y_TOP + 0.5, zz + 0.4)
        out.append(st)
        if x == 0.0:                                                                 # Christ with the cross
            out += [B(-0.95, -0.8, Y_TOP + 0.5, Y_TOP + 7.2, zz + 0.35, zz + 0.5, WHITE),
                    B(-1.6, -0.15, Y_TOP + 6.0, Y_TOP + 6.15, zz + 0.35, zz + 0.5, WHITE)]
    for s in (-1, 1):                                                                # balusters (as a pierced band)
        for x0, x1, zz in ((0.0, 27.9, zc), (27.9, 47.0, zs)):
            a, b = sorted((s * x0, s * x1))
            for u in np.arange(a + 0.3, b - 0.2, 0.55):
                out.append(B(u - 0.14, u + 0.14, Y_ACOR + 0.1, Y_TOP - 0.25, zz + 0.25, zz + 0.55, TRAV_L))
            out.append(B(a, b, Y_TOP - 0.25, Y_TOP, zz - 0.4, zz + 0.65, TRAV_L))
        x = s * 52.7                                                                 # clock of Valadier
        out += [B(x - 4.3, x + 4.3, Y_ACOR, 51.6, zs - 6.0, zs + 0.8, TRAV),
                B(x - 4.6, x + 4.6, 51.6, 52.3, zs - 6.3, zs + 1.1, TRAV_L),
                B(x - 4.5, x - 3.5, Y_ACOR, 51.6, zs - 0.2, zs + 1.0, TRAV_L), B(x + 3.5, x + 4.5, Y_ACOR, 51.6, zs - 0.2, zs + 1.0, TRAV_L),
                cyl(2.3, 2.3, 0.35, TRAV_L, 24).R(math.pi / 2, 0, 0).T(x, 48.4, zs + 1.15),
                cyl(1.95, 1.95, 0.1, WHITE, 24).R(math.pi / 2, 0, 0).T(x, 48.4, zs + 1.3),
                B(x - 0.07, x + 0.07, 48.3, 49.9, zs + 1.32, zs + 1.4, DARK), B(x - 0.06, x + 1.2, 48.33, 48.47, zs + 1.32, zs + 1.4, DARK),
                prism([(x - 4.0, 52.3), (x + 4.0, 52.3), (x, 54.6)], zs - 5.0, zs + 0.7, TRAV_L),
                sphere(0.55, TRAV_L, 8, 5).T(x, 54.4, zs - 2.0),
                B(x - 0.08, x + 0.08, 55.4, 56.6, zs - 2.08, zs - 1.92, IRON_C),
                B(x - 0.4, x + 0.4, 56.0, 56.12, zs - 2.08, zs - 1.92, IRON_C)]
    return merge(out)


IRON_C = (0.20, 0.20, 0.20)


# ── The sagrato, the steps and the square ────────────────────────────────────
def U_edge(x):
    """Front edge of the sagrato (OSM way 135747106): straight, with the semicircular landing in the middle."""
    d = x - 0.8
    if abs(d) < 12.0:
        return 195.8 + math.sqrt(12.0 ** 2 - d * d)
    return 195.8


def L_edge(x):
    return 222.0 + 0.0032 * (x - 1.5) ** 2


SAGRATO = [(-42.5, 131.0), (42.0, 131.0), (42.25, 141.35), (40.13, 170.09), (38.27, 195.69)] + \
          [(x, U_edge(x)) for x in np.linspace(12.8, -11.2, 17)] + [(-37.34, 195.89), (-42.01, 141.31)]


def split_z(m, knots):
    """Split the triangles of a flat mesh along the lines z = k (so a piecewise-linear level can be applied)."""
    V = [tuple(p) for p in m.v]; C = [tuple(c) for c in m.c]
    F = [tuple(f) for f in m.f]
    for k in knots:
        out = []
        cache = {}

        def mid(i, j):
            key = (min(i, j), max(i, j))
            if key not in cache:
                a, b = np.array(V[i]), np.array(V[j])
                t = (k - a[2]) / (b[2] - a[2])
                V.append(tuple(a + (b - a) * t)); C.append(C[i]); cache[key] = len(V) - 1
            return cache[key]
        for f in F:
            s = [V[i][2] - k for i in f]
            if all(v >= -1e-9 for v in s) or all(v <= 1e-9 for v in s):
                out.append(f); continue
            # rotate so that f[0] is alone on its side
            for r in range(3):
                a, b, c = f[r], f[(r + 1) % 3], f[(r + 2) % 3]
                sa, sb, sc = V[a][2] - k, V[b][2] - k, V[c][2] - k
                if (sa > 0) != (sb > 0) and (sa > 0) != (sc > 0) and abs(sb) > 1e-9 and abs(sc) > 1e-9:
                    p, q = mid(a, b), mid(a, c)
                    out += [(a, p, q), (p, b, c), (p, c, q)]
                    break
            else:
                out.append(f)
        F = out
    return Mesh(V, F, np.array(C))


def drape(m, lift=0.0):
    m = split_z(m, G_KNOTS[0][1:-1])
    m.v[:, 1] = g(m.v[:, 2]) + lift
    return m


def square():
    out = []
    pave = merge([cap(DATA["square"], 0.0, COBBLE), cap(DATA["retta"], 0.0, COBBLE)])
    out.append(drape(pave))
    for outer, inner in DATA["bands"]:                                           # the travertine frames of the 8 sectors
        out.append(drape(cap(outer, 0.0, BAND, holes=[inner]), 0.04))
    # the square seen from the side: a skirt under the paving edge going down
    for P in (DATA["square"], DATA["retta"]):
        w = walls(P, 0.0, 1.0, TRAV_D)
        w.v[:, 1] = np.where(w.v[:, 1] > 0.5, g(w.v[:, 2]) - 0.02, g(w.v[:, 2]) - 6.0)
        out.append(w)
    # the sagrato and its steps
    out.append(extrude(SAGRATO, -10.0, 0.0, TRAV_D, top_c=BAND).warp(
        lambda v: np.stack([v[:, 0], np.where(v[:, 1] > -1, -0.3 * np.clip((v[:, 2] - 136) / 60, 0, 1), v[:, 1]), v[:, 2]], 1)))
    N = 14
    xs = np.linspace(-37.3, 38.3, 41)
    top, bot = -0.3, float(g(224.0))
    h = (top - bot) / N
    for k in range(N - 1):
        f = (k + 1) / N
        front = [(x, U_edge(x) + (L_edge(x) - U_edge(x)) * f) for x in xs]
        back = [(x, U_edge(x) - 0.5) for x in xs]
        P = back + front[::-1]
        out.append(extrude(P, -9.0, top - (k + 1) * h, TRAV_L if k % 2 else BAND))
    # St Peter and St Paul at the foot of the steps
    for x in (-22.0, 23.0):
        y = float(g(229.0))
        out += [B(x - 1.6, x + 1.6, y - 1.0, y + 4.4, 227.4, 230.6, TRAV_L), B(x - 1.9, x + 1.9, y + 4.4, y + 4.9, 227.1, 230.9, TRAV_L),
                figure(5.55, WHITE, arm=1 if x < 0 else -1).T(x, y + 4.9, 229.0)]
    return merge(out)


# ── The obelisk and the fountains ────────────────────────────────────────────
def obelisk():
    P = np.array(DATA["obelisk"])
    cx, cz = P[:, 0].mean(), P[:, 1].mean()
    y = float(g(cz))
    out = [B(cx - 6.2, cx + 6.2, y - 2.0, y + 0.3, cz - 6.2, cz + 6.2, TRAV_D),
           B(cx - 5.2, cx + 5.2, y + 0.3, y + 0.6, cz - 5.2, cz + 5.2, TRAV_D),
           B(cx - 2.9, cx + 2.9, y + 0.6, y + 1.6, cz - 2.9, cz + 2.9, TRAV_L),
           B(cx - 2.5, cx + 2.5, y + 1.6, y + 6.6, cz - 2.5, cz + 2.5, (0.70, 0.62, 0.56)),
           B(cx - 2.8, cx + 2.8, y + 6.6, y + 7.3, cz - 2.8, cz + 2.8, TRAV_L),
           B(cx - 2.2, cx + 2.2, y + 7.3, y + 8.1, cz - 2.2, cz + 2.2, TRAV_L)]
    for sx in (-1, 1):                                                           # the four bronze lions
        for sz in (-1, 1):
            out.append(B(cx + sx * 1.15 - 0.55, cx + sx * 1.15 + 0.55, y + 8.1, y + 9.4, cz + sz * 1.15 - 0.55, cz + sz * 1.15 + 0.55, BRONZE))
    y0 = y + 9.4
    sh = 25.5
    V = []
    for yy, s in ((y0, 1.42), (y0 + sh, 0.98)):
        V += [(cx - s, yy, cz - s), (cx + s, yy, cz - s), (cx + s, yy, cz + s), (cx - s, yy, cz + s)]
    V.append((cx, y0 + sh + 1.4, cz))
    F = []
    for i in range(4):
        j = (i + 1) % 4
        F += [(i, j, 4 + j), (i, 4 + j, 4 + i), (4 + i, 4 + j, 8)]
    out.append(orient_out(Mesh(V, F, GRANITE)))
    yt = y0 + sh + 1.3
    out += [cyl(0.55, 0.45, 1.2, BRONZE, 8).T(cx, yt, cz),                        # Chigi mounts and star
            sphere(0.6, BRONZE, 8, 5).T(cx, yt + 1.2, cz),
            B(cx - 0.12, cx + 0.12, yt + 2.3, y + 41.0, cz - 0.12, cz + 0.12, BRONZE),
            B(cx - 0.8, cx + 0.8, y + 39.6, y + 39.85, cz - 0.12, cz + 0.12, BRONZE)]
    return merge(out)


def fountain(P):
    P = np.array(P)
    cx, cz = P[:, 0].mean(), P[:, 1].mean()
    R = (P[:, 0].max() - P[:, 0].min() + P[:, 1].max() - P[:, 1].min()) / 4         # ~5.15 m
    y = float(g(cz))
    out, wet = [], []
    out += [cyl(R + 1.6, R + 1.6, 2.2, TRAV_D, 40).T(cx, y - 2.0, cz),          # two travertine steps
            cyl(R + 0.8, R + 0.8, 0.25, TRAV_D, 40).T(cx, y + 0.2, cz)]
    rim = lathe([(R - 0.45, 0.45), (R - 0.45, 1.0), (R + 0.05, 1.05), (R + 0.15, 0.85), (R, 0.0)], TRAV_L, 40)
    out.append(rim.T(cx, y + 0.45, cz))
    wet.append(cyl(R - 0.45, R - 0.45, 0.01, WATER, 40).T(cx, y + 1.25, cz))
    out.append(lathe([(1.0, 0), (0.9, 1.0), (0.65, 2.6), (0.8, 3.4), (0.0, 3.5)], TRAV_L, 16).T(cx, y + 1.0, cz))
    # the great mushroom bowl with the water falling over it, a small bowl and the jet
    out.append(lathe([(0.6, 0.0), (1.8, 0.6), (2.9, 1.0), (3.0, 1.15), (0.0, 1.2)], TRAV_L, 24).T(cx, y + 4.4, cz))
    wet.append(lathe([(3.15, 0.0), (3.1, 0.6), (2.6, 1.15), (1.3, 1.5), (0.0, 1.6)], WATER, 24).T(cx, y + 5.4, cz))
    wet.append(lathe([(3.4, 0.0), (3.15, 1.0), (3.05, 1.1)], WATER, 24).T(cx, y + 4.4, cz))
    out.append(cyl(0.45, 0.35, 1.0, TRAV_L, 10).T(cx, y + 6.9, cz))
    out.append(lathe([(0.3, 0.0), (1.1, 0.35), (1.2, 0.5), (0.0, 0.55)], TRAV_L, 16).T(cx, y + 7.8, cz))
    wet.append(lathe([(0.25, 0.0), (0.12, 0.8), (0.0, 1.0)], WATER, 8).T(cx, y + 8.3, cz))
    return merge(out), merge(wet)


# ── Bernini's colonnade ──────────────────────────────────────────────────────
ARMS = {"n": {"c": (34.6, 322.1), "r": (66.43, 72.31, 78.98, 84.85), "a": (-66.6, 74.6), "gap": (-6.4, 5.0)},
        "s": {"c": (-28.9, 323.15), "r": (67.58, 73.4, 80.08, 85.94), "a": (101.2, 247.7), "gap": (174.0, 184.3)}}
C_TOP, C_ENT, C_COR, C_PAR = 14.0, 16.0, 16.9, 18.2


def tuscan(x, z, y0=0.6):
    r = 0.78
    return [B(x - 1.0, x + 1.0, y0, y0 + 0.45, z - 1.0, z + 1.0, TRAV_L),
            cyl(r * 1.1, r * 1.05, 0.35, TRAV_L, 10, caps=False).T(x, y0 + 0.45, z),
            cyl(r, r * 0.86, C_TOP - y0 - 1.6, tint(TRAV_L, 0.012), 10, caps=False).T(x, y0 + 0.8, z),
            cyl(r * 0.86, r * 1.12, 0.45, TRAV_L, 10, caps=False).T(x, C_TOP - 0.8, z),
            B(x - 1.0, x + 1.0, C_TOP - 0.35, C_TOP, z - 1.0, z + 1.0, TRAV_L)]


def sector(c, r0, r1, a0, a1, y0, y1, col, n):
    """A flat-topped curved slab between radii r0..r1 and angles a0..a1 (degrees)."""
    A = np.linspace(a0, a1, n)
    P = arc(*c, r1, a0, a1, n) + arc(*c, r0, a1, a0, n)
    return extrude(P, y0, y1, col)


def colonnade_arm(key, outline):
    A = ARMS[key]
    c, (r0, r1, r2, r3), (a0, a1), (g0, g1) = A["c"], A["r"], A["a"], A["gap"]
    rin, rout = r0 - 2.0, r3 + 2.2
    out = []
    # floor on three steps, the entablature on the OSM outline, the cornice, the parapets
    for k, d in enumerate((0.9, 0.45, 0.0)):
        out.append(extrude(offset(outline, d), -7.0, 0.2 * (k + 1), TRAV_D))
    out.append(extrude(outline, C_TOP, C_ENT, TRAV_L, top=False))
    out.append(extrude(offset(outline, 0.7), C_ENT, C_COR, TRAV_L, top_c=ROOF))
    out.append(ring_band(outline, 0.35, -0.5, C_COR, C_PAR, TRAV_L))
    # the pitched roof along the arc: ridge at the middle radius
    rm = (rin + rout) / 2
    n = max(8, int((a1 - a0) / 1.5))
    A_ = np.radians(np.linspace(a0 + 1.2, a1 - 1.2, n))
    V, F = [], []
    for i, t in enumerate(A_):
        for r, y in ((rin + 0.6, C_COR), (rm, 20.6), (rout - 0.6, C_COR)):
            V.append((c[0] + r * math.cos(t), y, c[1] + r * math.sin(t)))
    for i in range(n - 1):
        a, b = 3 * i, 3 * (i + 1)
        for k in range(2):
            F += [(a + k, b + k, b + k + 1), (a + k, b + k + 1, a + k + 1)]
    roof = Mesh(V, F, COL_ROOF)
    nn = np.cross(roof.v[F[0][1]] - roof.v[F[0][0]], roof.v[F[0][2]] - roof.v[F[0][0]])
    if nn[1] < 0:
        roof.f = roof.f[:, ::-1]
    out.append(roof)
    for t in (A_[0], A_[-1]):                                                    # hipped ends
        p = lambda r, y: (c[0] + r * math.cos(t), y, c[1] + r * math.sin(t))
        out.append(Mesh([p(rin + 0.6, C_COR), p(rout - 0.6, C_COR), p(rm, 20.6)], [(0, 1, 2), (0, 2, 1)], COL_ROOF))
    # pediments: the middle passage (facing the square and outwards) and the east end
    gm = math.radians((g0 + g1) / 2)
    for r, facing in ((rin - 0.4, gm + math.pi), (rout + 0.4, gm)):
        ped = merge([prism([(-7.5, C_COR), (7.5, C_COR), (0.0, 21.4)], -1.0, 0.6, TRAV_L),
                     prism([(-6.3, C_COR + 0.35), (6.3, C_COR + 0.35), (0.0, 20.8)], 0.6, 0.72, TRAV)])
        out.append(rot_y(ped, facing, c[0] + r * math.cos(gm), c[1] + r * math.sin(gm)))
    ae = math.radians(a1 if key == "n" else a0)                                  # east end of the arm
    tdir = ae + (math.pi / 2 if key == "n" else -math.pi / 2)
    ped = merge([prism([(-(rout - rin) / 2 - 0.4, C_COR), ((rout - rin) / 2 + 0.4, C_COR), (0.0, 21.6)], -1.5, 0.4, TRAV_L),
                 prism([(-(rout - rin) / 2 + 0.8, C_COR + 0.35), ((rout - rin) / 2 - 0.8, C_COR + 0.35), (0.0, 21.0)], 0.4, 0.52, TRAV)])
    out.append(rot_y(ped, tdir, c[0] + rm * math.cos(ae) + 0.6 * math.cos(tdir), c[1] + rm * math.sin(ae) + 0.6 * math.sin(tdir)))
    # the statues of saints over the inner edge
    lo, hi = a0 + 1.5, a1 - 1.5
    for t in np.radians(np.linspace(lo, hi, 49)):
        x, z = c[0] + (rin + 0.1) * math.cos(t), c[1] + (rin + 0.1) * math.sin(t)
        st = merge([B(-0.55, 0.55, C_PAR - 0.3, C_PAR + 0.35, -0.55, 0.55, TRAV_L), figure(3.2, TRAV_L, arm=1 if rng.random() < 0.5 else -1).T(0, C_PAR + 0.35, 0)])
        out.append(rot_y(st, t + math.pi, x, z))
    return out


def columns():
    out = []
    for x, z in DATA["columns"]:
        out += tuscan(x, z)
    return out


def corridor(P, toward):
    """Braccio di Costantino / di Carlo Magno: closed corridors with pilasters, windows, balustrade and statues."""
    out = [extrude(P, -7.0, 15.4, TRAV, top_c=ROOF)]
    out.append(ring_band(P, 0.3, -0.4, -7.0, 1.2, TRAV_D))
    out.append(ring_band(P, 0.45, -0.4, 13.6, 15.0, TRAV_L))
    out.append(ring_band(P, 1.0, -0.4, 15.0, 15.8, TRAV_L))
    out.append(ring_band(P, 0.3, -0.5, 15.8, 17.1, TRAV_L))
    Q = P if ring_area(P) > 0 else P[::-1]
    n = len(Q)
    for i in range(n):
        a, b = np.array(Q[i]), np.array(Q[(i + 1) % n])
        L = float(np.linalg.norm(b - a))
        t = (b - a) / L
        nrm = np.array([t[1], -t[0]])
        if L < 8 or nrm[0] * toward < 0.8:                                     # only the side facing the square
            continue
        loc = []
        k = max(1, round(L / 5.6))
        for j in range(k + 1):
            u = L * j / k
            loc.append(B(u - 0.6, u + 0.6, 1.2, 13.6, -0.1, 0.45, TRAV_L))
        for j in range(k):
            u = L * (j + 0.5) / k
            loc += window(u, 3.4, 7.4, 1.6, ped="tri" if j % 2 else "seg")
            loc += window(u, 9.8, 12.2, 1.4)
        out.append(to_frame(merge(loc), b, t))
    return out


def corridor_statues(line, k):
    out = []
    a, b = np.array(line[0], float), np.array(line[1], float)
    for f in np.linspace(0.04, 0.96, k):
        p = a + (b - a) * f
        st = merge([B(-0.55, 0.55, 16.8, 17.5, -0.55, 0.55, TRAV_L), figure(3.2, TRAV_L, arm=1 if rng.random() < 0.5 else -1).T(0, 17.5, 0)])
        out.append(rot_y(st, math.atan2(0, -np.sign(p[0])), p[0], p[1]))
    return out


def lift(m):
    m.v[:, 1] += g(m.v[:, 2]); return m


def build():
    parts = []
    parts.append(("basilica", body()))
    parts.append(("facade", facade()))
    parts.append(("roofs", roofs()))
    md = []
    for sx in (-1, 1):
        for sz in (-1, 1):
            md += minor_dome(sx * 37.25, sz * 37.1)
    parts.append(("minor_domes", merge(md)))
    parts.append(("dome", dome()))
    parts.append(("square", square()))
    ob = obelisk()
    fn, fw = fountain(DATA["fountain_n"])
    fs, fsw = fountain(DATA["fountain_s"])
    parts.append(("obelisk_fountains", merge([ob, fn, fs])))
    col = []
    col += colonnade_arm("n", DATA["colonnade_n"]) + colonnade_arm("s", DATA["colonnade_s"]) + columns()
    parts.append(("colonnade", lift(merge(col))))
    cor = corridor(DATA["braccio_n"], -1) + corridor(DATA["braccio_s"], 1)
    cor += corridor_statues([(54.0, 138.0), (52.0, 232.0)], 21) + corridor_statues([(-59.4, 138.0), (-48.2, 232.0)], 21)
    parts.append(("corridors", lift(merge(cor))))
    parts.append(("water", merge([fw, fsw]), {"material": "water"}))
    return parts


def footprint():
    """The basilica, the corridors, the colonnade and the square, +1 m (+0.5 m against the Apostolic Palace)."""
    Q = RING if ring_area(RING) > 0 else RING[::-1]
    Q = offset(Q, 1.0)
    # start at the north corner of the façade block and go round the apses to the south corner
    i0 = min(range(len(Q)), key=lambda i: (Q[i][0] - 58.35) ** 2 + (Q[i][1] - 119.1) ** 2)
    i1 = min(range(len(Q)), key=lambda i: (Q[i][0] + 58.35) ** 2 + (Q[i][1] - 119.1) ** 2)
    k = i0
    bas = []
    while True:
        bas.append(Q[k % len(Q)])
        if k % len(Q) == i1:
            break
        k += 1
    if not all(p[1] < 121 for p in bas):                     # wrong way round: go the other way
        bas, k = [], i0
        while True:
            bas.append(Q[k % len(Q)])
            if k % len(Q) == i1:
                break
            k -= 1
    fp = bas
    fp += [(-76.6, 117.0), (-71.3, 153.4), (-60.4, 229.3)]                                 # Braccio di Carlo Magno
    cs, cn = ARMS["s"]["c"], ARMS["n"]["c"]
    fp += arc(cs[0], cs[1], 89.2, 247.7, 101.2, 50)                                        # south arm
    fp += [(x, z + 1.0) for x, z in sorted((p for p in DATA["square"] if p[1] > 398 and abs(p[0]) < 46), key=lambda p: p[0])]
    fp += arc(cn[0], cn[1], 88.2, 74.6, -66.6, 48)                                         # north arm
    fp += [(66.7, 122.1), (58.35, 121.1)]                                                  # Braccio di Costantino
    return [(round(x, 1), round(z, 1)) for x, z in fp]


def main():
    parts = build()
    out_dir = ROOT / "models" / "Q12512"
    out_dir.mkdir(parents=True, exist_ok=True)
    named = []
    for p in parts:
        name, m = p[0], p[1]
        if name != "water":
            k = 0.94 + 0.06 * fbm(m.v, 0.05, 7, 2)
            m.c = np.clip(m.c * k[:, None], 0, 1)
        named.append(p)
    tris, size = write_glb(out_dir / "model.glb", named, roughness=0.88,
                           materials={"water": {"metallic": 0.0, "roughness": 0.12}})
    allv = np.vstack([p[1].v for p in named])
    lo, hi = allv.min(0), allv.max(0)
    print(f"{tris} triangles, {size / 1e6:.2f} MB, x {lo[0]:.1f}..{hi[0]:.1f} y {lo[1]:.1f}..{hi[1]:.1f} z {lo[2]:.1f}..{hi[2]:.1f}")
    for p in named:
        print(f"  {p[0]}: {len(p[1].f)}")
    meta = out_dir / "meta.json"
    if meta.exists():
        mj = json.loads(meta.read_text(encoding="utf-8"))
        mj["triangles"] = int(tris)
        mj["footprint"] = [list(p) for p in footprint()]
        meta.write_bytes((json.dumps(mj, ensure_ascii=False, indent=2) + "\n").encode("utf-8"))


if __name__ == "__main__":
    main()
